export function PublicLocaleProvider({ children }) {
  const [locale, setLocale] = useState(() => {
    try { return localStorage.getItem(KEY) === 'ar' ? 'ar' : 'en' } catch { return 'en' }
  })
  useEffect(() => {
    try { localStorage.setItem(KEY, locale) } catch { /* Preference remains available for this session. */ }
    document.documentElement.lang = locale
    document.documentElement.dir = locale === 'ar' ? 'rtl' : 'ltr'
    return () => { document.documentElement.lang = 'en'; document.documentElement.dir = 'ltr' }
  }, [locale])
  const value = useMemo(() => ({ locale, setLocale, direction: locale === 'ar' ? 'rtl' : 'ltr' }), [locale])
  return <PublicLocaleContext.Provider value={value}>{children}</PublicLocaleContext.Provider>
}

export function usePublicLocale() {
  const value = useContext(PublicLocaleContext)
  if (!value) throw new Error('usePublicLocale must be used within PublicLocaleProvider.')
  return value
}

export function translatePublicText(value) {
  if (typeof value !== 'string' || !value.trim()) return value
  const translated = ar[value.trim()] || roadmapAr[value.trim()]
  return translated ? value.replace(value.trim(), translated) : value
}

export function PublicLocaleTree({ children }) {
  const { locale, direction } = usePublicLocale()
  const visit = node => {
    if (typeof node === 'string') return locale === 'ar' ? translatePublicText(node) : node
    if (Array.isArray(node)) return node.map(visit)
    if (!React.isValidElement(node)) return node
    const props = { ...node.props }
    for (const key of ['aria-label', 'title', 'placeholder']) {
      if (typeof props[key] === 'string' && locale === 'ar') props[key] = translatePublicText(props[key])
    }
    if ('children' in props) props.children = visit(props.children)
    return React.cloneElement(node, props)
  }
  return <div lang={locale} dir={direction} className={`public-locale public-locale--${locale}`}>{visit(children)}</div>
}

export function PublicLanguageSwitcher({ compact = false }) {
  const { locale, setLocale } = usePublicLocale()
  return <div className={`public-language-switcher${compact ? ' public-language-switcher--compact' : ''}`} role="group" aria-label={locale === 'ar' ? translatePublicText('Website language') : 'Website language'}>
    <button type="button" lang="en" aria-pressed={locale === 'en'} onClick={() => setLocale('en')}>EN</button>
    <span aria-hidden="true">|</span>
    <button type="button" lang="ar" aria-pressed={locale === 'ar'} onClick={() => setLocale('ar')}>العربية</button>
  </div>
}
